CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS users(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),email TEXT UNIQUE NOT NULL,phone TEXT UNIQUE,full_name TEXT NOT NULL,password_hash TEXT NOT NULL,reset_token_hash TEXT,reset_expires_at TIMESTAMPTZ,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS wallets(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),user_id UUID UNIQUE NOT NULL REFERENCES users(id) ON DELETE CASCADE,currency TEXT NOT NULL DEFAULT 'NGN',balance_kobo BIGINT NOT NULL DEFAULT 0 CHECK(balance_kobo>=0),created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS ledger_entries(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),wallet_id UUID NOT NULL REFERENCES wallets(id),reference TEXT NOT NULL,type TEXT NOT NULL CHECK(type IN('CREDIT','DEBIT','REVERSAL')),amount_kobo BIGINT NOT NULL CHECK(amount_kobo>0),status TEXT NOT NULL CHECK(status IN('PENDING','COMPLETED','FAILED','REVERSED')),description TEXT NOT NULL,provider TEXT,provider_id TEXT,metadata JSONB NOT NULL DEFAULT '{}'::jsonb,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()); CREATE UNIQUE INDEX IF NOT EXISTS ledger_reference_uq ON ledger_entries(reference); CREATE INDEX IF NOT EXISTS ledger_wallet_created_idx ON ledger_entries(wallet_id,created_at DESC);
CREATE TABLE IF NOT EXISTS transfers(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),user_id UUID NOT NULL REFERENCES users(id),wallet_id UUID NOT NULL REFERENCES wallets(id),reference TEXT UNIQUE NOT NULL,provider_id TEXT,account_bank TEXT NOT NULL,account_number TEXT NOT NULL,beneficiary_name TEXT,amount_kobo BIGINT NOT NULL CHECK(amount_kobo>0),fee_kobo BIGINT NOT NULL DEFAULT 0 CHECK(fee_kobo>=0),currency TEXT NOT NULL DEFAULT 'NGN',status TEXT NOT NULL CHECK(status IN('PENDING','SUCCESSFUL','FAILED','REVERSED')),narration TEXT,provider_response JSONB,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS bill_payments(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),user_id UUID NOT NULL REFERENCES users(id),wallet_id UUID NOT NULL REFERENCES wallets(id),reference TEXT UNIQUE NOT NULL,biller_code TEXT NOT NULL,item_code TEXT NOT NULL,customer_id TEXT NOT NULL,amount_kobo BIGINT NOT NULL CHECK(amount_kobo>0),status TEXT NOT NULL DEFAULT 'PENDING',provider_response JSONB,created_at TIMESTAMPTZ DEFAULT NOW(),updated_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS kyc_submissions(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),user_id UUID NOT NULL REFERENCES users(id),document_type TEXT NOT NULL,document_last4 TEXT NOT NULL,photo_url TEXT,status TEXT NOT NULL DEFAULT 'PENDING',rejection_reason TEXT,created_at TIMESTAMPTZ DEFAULT NOW(),updated_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS user_settings(user_id UUID PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,security_2fa BOOLEAN NOT NULL DEFAULT FALSE,transaction_alerts BOOLEAN NOT NULL DEFAULT TRUE,login_alerts BOOLEAN NOT NULL DEFAULT TRUE,hide_balance BOOLEAN NOT NULL DEFAULT FALSE,theme TEXT NOT NULL DEFAULT 'system',currency TEXT NOT NULL DEFAULT 'NGN',updated_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS savings_goals(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),user_id UUID NOT NULL REFERENCES users(id),name TEXT NOT NULL,target_kobo BIGINT NOT NULL CHECK(target_kobo>0),saved_kobo BIGINT NOT NULL DEFAULT 0 CHECK(saved_kobo>=0),deadline DATE,created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS webhook_events(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),event_key TEXT UNIQUE NOT NULL,payload JSONB NOT NULL,received_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS pos_sales(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),user_id UUID NOT NULL REFERENCES users(id),reference TEXT UNIQUE NOT NULL,amount_kobo BIGINT NOT NULL CHECK(amount_kobo>0),currency TEXT NOT NULL DEFAULT 'NGN',description TEXT,status TEXT NOT NULL CHECK(status IN('PENDING','PAID','CANCELLED')),created_at TIMESTAMPTZ DEFAULT NOW());
